     button:focus-visible,
     input:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .status {
       min-height: 1.25em;
       color: #9fe3b3;
       font-size: 0.95rem;
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Terms of Use</h1>
     <p>Please review and agree to the terms to continue.</p>

     <form id="consent-form" novalidate>
       <div class="form-field">
         <div class="checkbox-row">
           <input id="consent" name="consent" type="checkbox" required>
           <div>
             <label for="consent">I agree to the terms of use</label>
             <div class="helper">You must accept the terms before submitting this form.</div>
           </div>
         </div>
       </div>

       <button type="submit">Submit</button>
       <div class="status" id="status" aria-live="polite"></div>
     </form>
   </main>

   <script>
     const form = document.getElementById('consent-form');
     const checkbox = document.getElementById('consent');
     const status = document.getElementById('status');

     form.addEventListener('submit', (event) => {
       event.preventDefault();

       if (!checkbox.checked) {
         status.textContent = 'Please accept the terms to submit.';
         checkbox.focus();
         return;
       }

       status.textContent = 'Consent submitted successfully.';
       form.reset();
     });
